    {
        hessian(0,0)=secDers(0,0);
    }
    if(ParDim==2)
    {
        hessian(0,0)=secDers(0,0);
        hessian(0,1)=secDers(2,0);
        hessian(1,0)=secDers(2,0);
        hessian(1,1)=secDers(1,0);
    }
    if(ParDim==3)
