+                  << " does not exist. There are only " << this->vertex.size() << " vertices." << std::endl;
+    }
+    return ((this->vertex[m_sorting[vertexIndex - 1]]));
+}
+
+std::size_t gsHalfEdgeMesh::getVertexIndex(const gsMesh<>::gsVertexHandle &vertex) const
