# Full function context (WaRF function-aware diff)

void read_iges_pd128(char *s, int begin, std::stringstream & ss)
{
    /* read 128 PD in IGES */
    static char t[FIELD_L+1];
    static int phase; /* 0-header, 1-cps, 2-knots, 3-weights */
    static int m;       /* marker in strings x, y, z */
    static int c, endknot;    /* counter of points */
    static int q[5],b[4]; /* b[0,1]-maxindex_of_ctrl_pts, b[2,3]-degree_of_Bspl */
    //static int sw[5]; /* breaks: 10, +b[0]+b[2]+2, +b[1]+b[3]+2, +(b[0]+1)*(b[1]+1), +(b[0]+1)*(b[1]+1) */
    int i;  /* i-order of the character */
    static int j;  /* j-order of head. */
    if (begin == 1)
    {
        phase=0;
        c=0;
        m=0;
        j=0;
        //sw[0]=10;
    }
    for (i=0; i <= 64; i++)
    {
        switch (phase)
        {
        case 0:  // PHASE header
            switch (j)
            {
            case 1:
            case 2:
            case 3:
            case 4:
                if (s[i] == ',')
                {
                    t[m]='\0';
                    b[j-1]=atoi(t);
                    j++; m=0;
                }
                else
                { t[m]=s[i]; m++; }
                break;
            default: //j=0, 5..9
                if (s[i] == ',')
                {
                    // j=0: 128
                    //(j=1..4: data in b[] ) 
                    // 5 integer parameters:
                    // j=5: closed in first direction
                    // j=6: closed in second direction
                    // j=7: rational
                    // j=8: periodic in first direction
                    // j=9: periodic in second direction

                    // b[0]+b[2]+2  u-knots
                    // b[1]+b[2]+2  v-knots
                    // (b[0]+1)*(b[1]+1) weights
                    // control points
                    t[m]= '\0';
                    m= 0;
                    //printf("%d: Got number: %s\n", j, t);
                    if (0!=j) q[j-5]= atoi(t);
                    if (7==j) ss<<q[0]<<",";
                    j++;
                }
                else
                {                                  /* digit + - E e D d */
                    t[m]= s[i];
                    m++;
                    break;
                }
                if ( 10 == j )
                {
                    endknot = b[0]+b[2]+2+b[1]+b[3]+2;   
                    phase=1; // knots start
                }
            }
            break;
        case 3:  // PHASE CP
            if (s[i] == ' ') return;
            else if (s[i] == ',' || s[i] == ';')  /* the last coordinate */
            {
                t[m]='\0';
                format_number(t);
                ss <<" "<< t;
                m= 0;
                c++;
                if (c == 3*(b[0]+1)*(b[1]+1))
                {
                    c=0;
                    return;
                }
            }
            else
            {                                  /* digit + - E e D d */
                t[m]= s[i];
                m++;
            }
            break;
        case 1:  // PHASE knots
            if (s[i] == ' ') return;
            else if (s[i] == ',')
            {                 /* next knot */
                t[m]= '\0';
                format_number(t);
                ss <<" "<< t;
                m= 0;
                c++;
                if (c == b[0]+b[2]+2) ss<<","<<b[2]<<",";
            }
            else {                                  /* digit + - E e D d */
                t[m]= s[i];
                m++;
                break;
            }

            if (c == endknot)
            {
                ss<<","<<b[3]<<",";
                c=0;
                phase=2; //weights start
            }
            break;
        case 2:  // PHASE weights
            if (s[i] == ' ') return;
            else if (s[i] == ',')
            {                 /* next knot */
                t[m]= '\0';
                format_number(t);
                ss <<" "<< t;
                m= 0;
                c++;
            }
            else {                                  /* digit + - E e D d */
                t[m]= s[i];
                m++;
                break;
            }

            if (c == (b[0]+1)*(b[1]+1))
            {
                ss<<",";
                c=0;
                phase=3; //control points start
            }
            break;
        }
    }
}


