+template<class T>
+void gsFastFitting<T>::GridProjection(const gsMatrix<T> &ugrid, const gsMatrix<T> &vgrid, gsMatrix<index_t>& weights)
+{
+    // For now the identity:
+    index_t n1,n2;
+    n1 = weights.rows();
+    n2 = weights.cols();
+    weights.setZero(n1,n2);
