    A.assembleBdr(bc.get("Neumann"), u * g_N * tv(G).norm() );

    A.assemble(
        (N_der * (E_m_der).tr() + M_der * (E_f_der).tr() ) * meas(G)
        ,
        u * F  * meas(G) + pressure * u * sn(defG).normalized() * meas(G)
        );

