+/**
+ * Benchmark metrics
+ */
+enum metric {
+  bandwidth_kb_sec,
+  bandwidth_mb_sec,
+  bandwidth_gb_sec,
+  bandwidth_tb_sec,  
+  perf_kflop_sec,
+  perf_mflop_sec,
+  perf_gflop_sec,
+  perf_tflop_sec,  
+  runtime_sec,
+};
+
