+##
+## gsFupBasis extension
+##
+include_directories(SYSTEM ${OCC_INCLUDE_DIR})
+set(FUP_FORT_SOURCES ModuleFup.f90)
+
+# Compile the extension as part of the G+Smo library
+add_library(${PROJECT_NAME} OBJECT ${FUP_FORT_SOURCES})
+
