+        assembler.assemble(x, fixedDofs);
+        m = assembler.matrix();
+        return true;
+    };
+
+    // Function for the Residual
+    gsStructuralAnalysisOps<real_t>::TResidual_t Residual = [&assembler,&fixedDofs](gsMatrix<real_t> const &x, real_t t, gsVector<real_t> & result)
