+                collection.addTimestep(fileName,time,".vts");
+            }
+            solution.patch(0).eval_into(points,pointDataMatrix);
+            otherDataMatrix<<time;
+            writer.add(pointDataMatrix,otherDataMatrix);
+        }
+    }
