+                    r = kernel.rank(k*d + q);
+                    A.cleanUp();
+
+                    auto u_q = A.getSpace(hbs, s, r); //r,0
+                    auto v_k = A.getTestSpace(hbs, 1);
+                    auto w_kq  = A.getCoeff(kernel.component(s));
+                    A.initMatrix();
+            
+                    switch ( (k==s) + 2 *(q==s) )
+                    {
+                    default://0
+                        A.assemble(v_k * w_kq.tr() * u_q.tr());
+                        break;
+                    case 1:
+                        A.assemble(grad(v_k)* w_kq.tr() * u_q.tr());
+                        break;
+                    case 2:
+                        A.assemble(v_k * w_kq.tr() * grad(u_q).tr());
+                        break;
+                    case 3:
