+    gsTensorFunction(short_t _dim = 2, int type = 0) : m_skeleton(_dim)
+    {
+        // /*
+        const index_t sz = (0==type ? 1 : _dim);
+        gsMatrix<T> mm = gsMatrix<T>::Identity(sz,sz);
+        mm.resize(sz*sz,1);
