+namespace gismo
+{
+template<typename Derived>
+inline bool is_finite(const gsEigen::MatrixBase<Derived>& x)
+{
+   return ( (x - x).array() == (x - x).array()).all();
+}
+
+template<typename Derived>
+inline bool is_nan_free(const gsEigen::MatrixBase<Derived>& x)
+{
+    return ((x.array() == x.array())).all();
+}
+}
